-- -*- mode: lua -*-

-- MIDI map for the AKAI APC mini mk2.
-- Albert Gräf <agggraef@gmail.com>, 1 May 2024

-- NOTE: The driver will only work with the mk2 version of the device, the
-- original APC mini is *not* supported. You need to set up the MIDI
-- connections as follows:

-- The APC mini mk2 "Notes" port goes into Pd's first input port for the notes
-- input in NOTE mode (see below).

-- The APC mini mk2 "Control" port needs to be hooked up to Pd's port 3 or 4;
-- use the same port number on both input and output. Also make sure that you
-- don't have a Launchpad connected to that port, as the two devices are
-- incompatible and can't be used on the same MIDI port.

-- Then load this map into Raptor and you should be set.

-- Most of the special functionality can be accessed with the strip of eight
-- "track" buttons and the SHIFT button right above the faders. Normally these
-- buttons have the functions indicated by the labels, allowing you to select
-- fader banks with the FADER CTRL buttons, presets (up/down arrow buttons),
-- and Raptor instances (left/right arrow buttons). When you press the SHIFT
-- button, the eight buttons change to a special selection mode in which you
-- can select a Raptor instance among the first eight, with the current
-- instance being hightlighted as long as you hold the SHIFT button. This is
-- all hard-wired functionality provided by the driver.

-- The map assigns the same two bottom rows of pads in session mode as on the
-- Launchpad, and five fader banks which can be switched with the FADER CTRL
-- buttons. These are the same five banks (albeit using different CCs) as on
-- the Launchpad and Launchkey. See the doc/raptor7-cheatsheet.pdf file for an
-- overview of the preconfigured controls and pads.

-- Note that, as the APC mini only has four fader bank buttons, the fifth
-- "Extra" bank is accessed by turning all FADER CTRL buttons *off*. Also, the
-- device has a ninth fader which the driver has hard-wired to CC7 (volume),
-- like the ninth fader on the Launchkey (49+), so that you can use it to
-- control the master volume of your synth.

-- The (unshifted) SOLO, MUTE, and REC ARM buttons are assigned to latch,
-- mute, and bypass. (These functions are also available as pads in the
-- session view, but it's convenient to also have them on tap in the other
-- modes when you're playing notes or drums, see below.) The other scene
-- launch buttons in the vertical strip on the right aren't predefined at
-- present, so you're free to map them as you see fit.

-- By pressing SHIFT along with the NOTE and DRUM buttons, you can switch
-- between the default session mode and the built-in note and drum modes of
-- the APC mini mk2. In DRUM mode, you have the same layout of four 4x4 grids
-- in different colors as on the Launchpad, with note 36 in the lower-left
-- corner. (Also note that while holding the SHIFT key, the NOTE and DRUM
-- buttons will light up if the corresponding mode is active, thereby
-- indicating the button you need to press to return to session mode.)

-- CAVEAT: The driver only supports a single APC mini mk2 device at present.
-- But you can run the APC mini in tandem with a Launchpad, if you connect
-- them to different ports. We recommend that in this case you connect the
-- Launchpad to port 3 and the APC mini to port 4. By these means both devices
-- should also work in "standalone" mode, with the corresponding drivers
-- turned off. (Both devices are much less useful without driver support, so I
-- wouldn't know why you'd want to run such a setup, but YMMV.)

{
  -- send A (min value) faders
  [13] = { [49] = "minvel" },
  [14] = { [49] = "pmin" },
  [15] = { [49] = "wmin" },
  [16] = { [49] = "gate" },
  [17] = { [49] = "hmin" },
  [18] = { [49] = "pref" },
  [19] = { [49] = "smin" },
  [20] = { [49] = "uniq" },
  -- send B (max value) faders
  [29] = { [49] = "maxvel" },
  [30] = { [49] = "pmax" },
  [31] = { [49] = "wmax" },
  [32] = { [49] = "gate" },
  [33] = { [49] = "hmax" },
  [34] = { [49] = "pref" },
  [35] = { [49] = "smax" },
  [36] = { [49] = "nmax" },
  -- pan (bipolar mod) faders
  [37] = { [49] = "velmod" },
  [38] = { [49] = "pmod" },
  [39] = { [49] = "gain" },
  [40] = { [49] = "gatemod" },
  [41] = { [49] = "hmod" },
  [42] = { [49] = "prefmod" },
  [43] = { [49] = "smod" },
  [44] = { [49] = "nmod" },
  -- volume faders
  [48] = { [49] = "pitchhi" },
  [49] = { [49] = "pitchlo" },
  [50] = { [49] = "mode" },
  [51] = { [49] = "pos" },
  [52] = { [49] = "tempo" },
  [53] = { [49] = "meter-num" },
  [54] = { [49] = "meter-denom" },
  [55] = { [49] = "division" },
  -- "extra" bank (selection of most frequently used controls)
  [21]  = { [49] = "mode" },
  [22]  = { [49] = "pos" },
  [23]  = { [49] = "gain" },
  [24]  = { [49] = "gate" },
  [25]  = { [49] = "hmin" },
  [26]  = { [49] = "hmax" },
  [27]  = { [49] = "pref" },
  [28]  = { [49] = "prefmod" },
  -- predefined pads (session view)
  -- 128, 129 unassigned
  [130] = { [49] = { "raptor", true } },
  [131] = { [49] = { "rewind", true } },
  -- 132 unassigned
  [133] = { [49] = { "loop-prev", true } },
  [134] = { [49] = { "loop-next", true } },
  [135] = { [49] = { "play", true } },
  -- upper row
  [136] = { [49] = { "mute", true } },
  [137] = { [49] = { "latch", true } },
  [138] = { [49] = { "bypass", true } },
  -- 139, 140 unassigned
  [141] = { [49] = { "loop-load", true } },
  [142] = { [49] = { "loop-save", true } },
  [143] = { [49] = { "loop", true } },
  -- SOLO, MUTE, REC ARM buttons
  [241] = { [49] = { "latch", true } },
  [242] = { [49] = { "mute", true } },
  [243] = { [49] = { "bypass", true } },
}
